WITH valid AS (SELECT id, product_name, brand, price, stock_qty, tags, supplier_id, SUBSTRING(brand, 1, 2) AS brand_prefix FROM products WHERE brand IS NOT NULL AND product_name LIKE 'W%') SELECT p.country, e.brand, COUNT(*) AS rows_total, ROUND(SUM(e.stock_qty), 2) AS total_stock_qty, SUM(e.price) AS total_price FROM valid e INNER JOIN suppliers p ON e.supplier_id = p.id GROUP BY p.country, e.brand ORDER BY total_price DESC NULLS LAST;
